{"sql": "-- Enable RLS on all tables
ALTER TABLE public.users ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.channels ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.posts ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.comments ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.channel_moderators ENABLE ROW LEVEL SECURITY;"}

{"sql": "-- Channels Table RLS Policies

-- SELECT: Everyone can read public channel information
CREATE POLICY channels_select_policy ON public.channels
FOR SELECT
USING (
    is_public = true OR 
    owner_id = public.current_user_id() OR
    public.is_channel_moderator(id, public.current_user_id())
);

-- INSERT: Any authenticated user can create a channel (becomes owner)
CREATE POLICY channels_insert_policy ON public.channels
FOR INSERT
WITH CHECK (
    public.current_user_id() IS NOT NULL AND
    owner_id = public.current_user_id()
);

-- UPDATE: Only channel owners can modify channel details
CREATE POLICY channels_update_policy ON public.channels
FOR UPDATE
USING (
    public.is_channel_owner(id, public.current_user_id())
)
WITH CHECK (
    public.is_channel_owner(id, public.current_user_id())
);

-- DELETE: Only channel owners can delete channels
CREATE POLICY channels_delete_policy ON public.channels
FOR DELETE
USING (
    public.is_channel_owner(id, public.current_user_id())
);"}

{"sql": "-- Posts Table RLS Policies

-- SELECT: Users can read all posts in channels they have access to
CREATE POLICY posts_select_policy ON public.posts
FOR SELECT
USING (
    EXISTS (
        SELECT 1
        FROM public.channels
        WHERE channels.id = posts.channel_id
        AND (
            channels.is_public = true OR
            channels.owner_id = public.current_user_id() OR
            public.is_channel_moderator(channels.id, public.current_user_id())
        )
    )
);

-- INSERT: Authenticated users can create posts in any channel
CREATE POLICY posts_insert_policy ON public.posts
FOR INSERT
WITH CHECK (
    public.current_user_id() IS NOT NULL AND
    author_id = public.current_user_id() AND
    EXISTS (
        SELECT 1
        FROM public.channels
        WHERE channels.id = posts.channel_id
        AND (
            channels.is_public = true OR
            channels.owner_id = public.current_user_id() OR
            public.is_channel_moderator(channels.id, public.current_user_id())
        )
    )
);

-- UPDATE: Post authors OR channel moderators OR channel owners can edit posts
CREATE POLICY posts_update_policy ON public.posts
FOR UPDATE
USING (
    author_id = public.current_user_id() OR
    public.can_moderate_channel(channel_id, public.current_user_id())
)
WITH CHECK (
    author_id = public.current_user_id() OR
    public.can_moderate_channel(channel_id, public.current_user_id())
);

-- DELETE: Post authors OR channel moderators OR channel owners can delete posts
CREATE POLICY posts_delete_policy ON public.posts
FOR DELETE
USING (
    author_id = public.current_user_id() OR
    public.can_moderate_channel(channel_id, public.current_user_id())
);"}

{"sql": "-- Comments Table RLS Policies

-- SELECT: Users can read comments on posts they can access
CREATE POLICY comments_select_policy ON public.comments
FOR SELECT
USING (
    EXISTS (
        SELECT 1
        FROM public.posts
        JOIN public.channels ON channels.id = posts.channel_id
        WHERE posts.id = comments.post_id
        AND (
            channels.is_public = true OR
            channels.owner_id = public.current_user_id() OR
            public.is_channel_moderator(channels.id, public.current_user_id())
        )
    )
);

-- INSERT: Authenticated users can comment on posts they can see
CREATE POLICY comments_insert_policy ON public.comments
FOR INSERT
WITH CHECK (
    public.current_user_id() IS NOT NULL AND
    author_id = public.current_user_id() AND
    EXISTS (
        SELECT 1
        FROM public.posts
        JOIN public.channels ON channels.id = posts.channel_id
        WHERE posts.id = comments.post_id
        AND (
            channels.is_public = true OR
            channels.owner_id = public.current_user_id() OR
            public.is_channel_moderator(channels.id, public.current_user_id())
        )
    )
);

-- UPDATE: Comment authors OR post authors OR channel moderators OR channel owners can edit comments
CREATE POLICY comments_update_policy ON public.comments
FOR UPDATE
USING (
    author_id = public.current_user_id() OR
    EXISTS (
        SELECT 1
        FROM public.posts
        WHERE posts.id = comments.post_id
        AND (
            posts.author_id = public.current_user_id() OR
            public.can_moderate_channel(posts.channel_id, public.current_user_id())
        )
    )
)
WITH CHECK (
    author_id = public.current_user_id() OR
    EXISTS (
        SELECT 1
        FROM public.posts
        WHERE posts.id = comments.post_id
        AND (
            posts.author_id = public.current_user_id() OR
            public.can_moderate_channel(posts.channel_id, public.current_user_id())
        )
    )
);

-- DELETE: Comment authors OR post authors OR channel moderators OR channel owners can delete comments
CREATE POLICY comments_delete_policy ON public.comments
FOR DELETE
USING (
    author_id = public.current_user_id() OR
    EXISTS (
        SELECT 1
        FROM public.posts
        WHERE posts.id = comments.post_id
        AND (
            posts.author_id = public.current_user_id() OR
            public.can_moderate_channel(posts.channel_id, public.current_user_id())
        )
    )
);"}

{"sql": "-- Channel Moderators Table RLS Policies

-- SELECT: Users can see moderator lists for channels
CREATE POLICY channel_moderators_select_policy ON public.channel_moderators
FOR SELECT
USING (
    EXISTS (
        SELECT 1
        FROM public.channels
        WHERE channels.id = channel_moderators.channel_id
        AND (
            channels.is_public = true OR
            channels.owner_id = public.current_user_id() OR
            public.is_channel_moderator(channels.id, public.current_user_id())
        )
    )
);

-- INSERT: Only channel owners can add moderators
CREATE POLICY channel_moderators_insert_policy ON public.channel_moderators
FOR INSERT
WITH CHECK (
    public.is_channel_owner(channel_id, public.current_user_id()) AND
    user_id != public.current_user_id() -- Owners can't add themselves as moderators
);

-- DELETE: Channel owners can remove moderators; moderators can remove themselves
CREATE POLICY channel_moderators_delete_policy ON public.channel_moderators
FOR DELETE
USING (
    public.is_channel_owner(channel_id, public.current_user_id()) OR
    user_id = public.current_user_id()
);"}

{"sql": "-- Additional indexes for RLS performance

-- Index on posts for channel_id and author_id combination
CREATE INDEX IF NOT EXISTS idx_posts_channel_author ON public.posts(channel_id, author_id);

-- Index on comments for post_id and author_id combination
CREATE INDEX IF NOT EXISTS idx_comments_post_author ON public.comments(post_id, author_id);

-- Index on channel_moderators for channel_id lookups
CREATE INDEX IF NOT EXISTS idx_channel_moderators_channel ON public.channel_moderators(channel_id);

-- Index on channels for owner_id lookups
CREATE INDEX IF NOT EXISTS idx_channels_owner ON public.channels(owner_id);"}

{"sql": "-- Fix the users SELECT policy to only show public users and current user
DROP POLICY users_select_policy ON public.users;

CREATE POLICY users_select_policy ON public.users
FOR SELECT
USING (
    is_public = true OR 
    id = public.current_user_id()
);"}

{"sql": "-- Fix the current_user_id function
CREATE OR REPLACE FUNCTION public.current_user_id()
RETURNS uuid
LANGUAGE plpgsql
STABLE
AS $$
BEGIN
    RETURN current_setting('app.current_user_id', true)::uuid;
EXCEPTION WHEN OTHERS THEN
    RETURN NULL;
END;
$$;"}

